/* 학습 해설
 * 참조 카운트 · 객체 수명과 마지막 참조
 * 여러 실행 흐름이 같은 객체를 사용할 때 마지막 사용자가 끝난 뒤에만 해제해야 합니다.
 * 참조를 얻을 때 증가시키고 반납할 때 감소시킵니다. 마지막 참조의 감소를 확인한 실행 흐름이 객체를 정리합니다. refcount_t는 일반 atomic 정수와 달리 수명 관리 오버플로 등을 방어하는 규칙을 갖습니다.
 * 이미 해제될 수 있는 포인터에 무조건 증가를 수행하면 안 됩니다. 객체 획득 경로의 잠금·RCU와 refcount_inc_not_zero 같은 규칙을 함께 확인합니다.
 */
static inline __must_check bool refcount_dec_and_test(refcount_t *r)
{
	return __refcount_dec_and_test(r, NULL);
}

static inline void __refcount_dec(refcount_t *r, int *oldp)
{
	int old = atomic_fetch_sub_release(1, &r->refs);

	if (oldp)
		*oldp = old;

	if (unlikely(old <= 1))
		refcount_warn_saturate(r, REFCOUNT_DEC_LEAK);
}

/**
 * refcount_dec - decrement a refcount
 * @r: the refcount
 *
 * Similar to atomic_dec(), it will WARN on underflow and fail to decrement
 * when saturated at REFCOUNT_SATURATED.
 *
 * Provides release memory ordering, such that prior loads and stores are done
 * before.
 */

