/* 학습 해설
 * Per-CPU · 지역 상태와 캐시 경합
 * 모든 CPU가 하나의 카운터를 수정하면 잠금과 캐시 라인 전달 비용이 커집니다.
 * CPU마다 별도 저장 공간을 두어 지역 업데이트를 분산합니다. 전체 값은 각 CPU의 값을 합쳐 얻습니다. 현재 CPU를 사용하는 동안 CPU 이동·선점·인터럽트 접근 규약을 고려해야 합니다.
 * this_cpu 계열과 per_cpu 접근의 의미를 구분합니다. 전체 집계가 업데이트 중간에 이루어지면 완벽한 단일 시점 스냅샷이 아닐 수 있습니다.
 */
void __percpu *pcpu_alloc_noprof(size_t size, size_t align, bool reserved,
				 gfp_t gfp)
{
	gfp_t pcpu_gfp;
	bool is_atomic;
	bool do_warn;
	struct obj_cgroup *objcg = NULL;
	static int warn_limit = 10;
	struct pcpu_chunk *chunk, *next;
	const char *err;
	int slot, off, cpu, ret;
	unsigned long flags;
	void __percpu *ptr;
	size_t bits, bit_align;

	gfp = current_gfp_context(gfp);
	/* whitelisted flags that can be passed to the backing allocators */
	pcpu_gfp = gfp & (GFP_KERNEL | __GFP_NORETRY | __GFP_NOWARN);
	is_atomic = (gfp & GFP_KERNEL) != GFP_KERNEL;
	do_warn = !(gfp & __GFP_NOWARN);

	/*
	 * There is now a minimum allocation size of PCPU_MIN_ALLOC_SIZE,
	 * therefore alignment must be a minimum of that many bytes.
	 * An allocation may have internal fragmentation from rounding up
	 * of up to PCPU_MIN_ALLOC_SIZE - 1 bytes.
	 */

