/* 학습 해설
 * Softirq · 지연된 인터럽트 처리
 * 하드 IRQ에서는 짧게 응답하고 많은 후속 작업은 다른 처리 단계로 미뤄야 합니다.
 * pending 비트를 확인해 등록된 softirq 작업을 실행합니다. 시간·재시작 제한 등을 넘으면 ksoftirqd에 처리를 넘길 수 있습니다. 네트워크 처리에서 사용되며 일반적인 softirq 컨텍스트를 자유롭게 잠드는 태스크로 취급하면 안 됩니다.
 * 작업 컨텍스트의 수면 가능 여부부터 확인합니다. 사용자 공간에서는 /proc/softirqs로 종류별·CPU별 처리 횟수를 관찰할 수 있습니다.
 */
asmlinkage __visible void __softirq_entry __do_softirq(void)
{
	handle_softirqs(false);
}

/**
 * irq_enter_rcu - Enter an interrupt context with RCU watching
 */
void irq_enter_rcu(void)
{
	__irq_enter_raw();

	if (tick_nohz_full_cpu(smp_processor_id()) ||
	    (is_idle_task(current) && (irq_count() == HARDIRQ_OFFSET)))
		tick_irq_enter();

	account_hardirq_enter(current);
}

/**
 * irq_enter - Enter an interrupt context including RCU update
 */
void irq_enter(void)
{
	ct_irq_enter();
	irq_enter_rcu();

