/* 학습 해설
 * Workqueue · 태스크 문맥의 지연 작업
 * 나중에 실행할 작업이 잠드는 API를 사용해야 한다면 태스크 문맥이 필요합니다.
 * work 구조체를 큐에 넣고 worker 태스크가 콜백을 수행합니다. 같은 work의 중복 대기와 실행·재큐잉 규칙이 있으며 worker 수와 동시성은 workqueue 설정에 영향을 받습니다.
 * INIT_WORK와 queue_work를 사용하고 객체를 해제할 때 cancel_work_sync 또는 해당 수명 규약으로 실행 종료를 보장합니다. 큐에 넣었다는 사실은 작업 완료를 뜻하지 않습니다.
 */
bool queue_work_on(int cpu, struct workqueue_struct *wq,
		   struct work_struct *work)
{
	bool ret = false;
	unsigned long irq_flags;

	local_irq_save(irq_flags);

	if (!test_and_set_bit(WORK_STRUCT_PENDING_BIT, work_data_bits(work)) &&
	    !clear_pending_if_disabled(work)) {
		__queue_work(cpu, wq, work);
		ret = true;
	}

	local_irq_restore(irq_flags);
	return ret;
}
EXPORT_SYMBOL(queue_work_on);

/**
 * select_numa_node_cpu - Select a CPU based on NUMA node
 * @node: NUMA node ID that we want to select a CPU from
 *
 * This function will attempt to find a "random" cpu available on a given
 * node. If there are no CPUs available on the given node it will return
 * WORK_CPU_UNBOUND indicating that we should just schedule to any
 * available CPU if we need to schedule this work.
 */

