/* 학습 해설
 * Hrtimer · 고해상도 만료 시각
 * 작은 시간 간격과 정확한 만료 시점이 필요한 작업은 단순 tick 카운터보다 세밀한 타이머가 필요합니다.
 * 고해상도 타이머는 만료 시각을 순서대로 관리하고 가까운 만료를 clockevent에 연결합니다. 만료 범위 slack은 타이머를 묶어 처리할 여지를 줍니다. 요청 시각과 실제 콜백 실행 시각은 다를 수 있습니다.
 * 절대·상대 모드와 타이머 콜백 컨텍스트를 확인합니다. hrtimer_cancel로 실행과 수명을 정리하며 사용자 공간에서는 clock_nanosleep의 모드를 비교할 수 있습니다.
 */
void hrtimer_start_range_ns(struct hrtimer *timer, ktime_t tim,
			    u64 delta_ns, const enum hrtimer_mode mode)
{
	struct hrtimer_clock_base *base;
	unsigned long flags;

	if (WARN_ON_ONCE(!timer->function))
		return;
	/*
	 * Check whether the HRTIMER_MODE_SOFT bit and hrtimer.is_soft
	 * match on CONFIG_PREEMPT_RT = n. With PREEMPT_RT check the hard
	 * expiry mode because unmarked timers are moved to softirq expiry.
	 */
	if (!IS_ENABLED(CONFIG_PREEMPT_RT))
		WARN_ON_ONCE(!(mode & HRTIMER_MODE_SOFT) ^ !timer->is_soft);
	else
		WARN_ON_ONCE(!(mode & HRTIMER_MODE_HARD) ^ !timer->is_hard);

	base = lock_hrtimer_base(timer, &flags);

	if (__hrtimer_start_range_ns(timer, tim, delta_ns, mode, base))
		hrtimer_reprogram(timer, true);

	unlock_hrtimer_base(timer, &flags);
}
EXPORT_SYMBOL_GPL(hrtimer_start_range_ns);

