/* 학습 해설
 * 시간 유지 · Clocksource와 단조 시계
 * 하드웨어 카운터를 시간으로 바꾸고 일시 조정과 경과 시간을 서로 구분해야 합니다.
 * clocksource의 카운터 차이를 배율로 변환해 시간을 누적합니다. CLOCK_REALTIME은 벽시계 조정을 반영하며 CLOCK_MONOTONIC은 일반 벽시계 변경에 의해 뒤로 가지 않는 경과 시간 기준입니다. suspend 포함 여부도 시계마다 다릅니다.
 * 경과 시간 측정에는 적합한 단조 시계를 선택하고 달력 표시에는 realtime을 씁니다. suspend를 포함하려면 BOOTTIME의 의미를 확인합니다.
 */
ktime_t ktime_get(void)
{
	struct timekeeper *tk = &tk_core.timekeeper;
	unsigned int seq;
	ktime_t base;
	u64 nsecs;

	WARN_ON(timekeeping_suspended);

	do {
		seq = read_seqcount_begin(&tk_core.seq);
		base = tk->tkr_mono.base;
		nsecs = timekeeping_get_ns(&tk->tkr_mono);

	} while (read_seqcount_retry(&tk_core.seq, seq));

	return ktime_add_ns(base, nsecs);
}
EXPORT_SYMBOL_GPL(ktime_get);

u32 ktime_get_resolution_ns(void)
