/* 학습 해설
 * vmalloc · 가상 연속과 물리 연속
 * 큰 커널 버퍼를 만들 때 물리적으로 긴 연속 공간을 확보하기 어려울 수 있습니다.
 * 서로 떨어진 물리 페이지를 연속된 커널 가상 주소에 매핑합니다. kmalloc의 물리 연속 특성과 다르며 페이지 테이블 구성·TLB 비용이 추가됩니다.
 * vmalloc 버퍼를 일반 단일 DMA 버퍼처럼 직접 장치에 전달하지 않습니다. 필요한 경우 페이지별·scatterlist 등 올바른 DMA 매핑 경로를 사용합니다.
 */
void *vmalloc_noprof(unsigned long size)
{
	return __vmalloc_node_noprof(size, 1, GFP_KERNEL, NUMA_NO_NODE,
				__builtin_return_address(0));
}
EXPORT_SYMBOL(vmalloc_noprof);

/**
 * vmalloc_huge - allocate virtually contiguous memory, allow huge pages
 * @size:      allocation size
 * @gfp_mask:  flags for the page level allocator
 *
 * Allocate enough pages to cover @size from the page level
 * allocator and map them into contiguous kernel virtual space.
 * If @size is greater than or equal to PMD_SIZE, allow using
 * huge pages for the memory
 *
 * Return: pointer to the allocated memory or %NULL on error
 */
void *vmalloc_huge_noprof(unsigned long size, gfp_t gfp_mask)
{
	return __vmalloc_node_range_noprof(size, 1, VMALLOC_START, VMALLOC_END,
				    gfp_mask, PAGE_KERNEL, VM_ALLOW_HUGE_VMAP,
				    NUMA_NO_NODE, __builtin_return_address(0));
}
EXPORT_SYMBOL_GPL(vmalloc_huge_noprof);

