/* 학습 해설
 * 마운트·Namespace · 경로 트리 연결
 * 서로 다른 파일시스템을 하나의 경로 트리에 연결하고 실행 환경마다 다른 트리를 보여줄 수 있어야 합니다.
 * 마운트 객체가 파일시스템의 루트를 경로 위치에 연결합니다. mount namespace는 이 연결의 보기를 분리하며 공유·전파 속성이 마운트 이벤트의 전달을 결정합니다.
 * findmnt와 /proc/self/mountinfo로 실제 연결을 조회합니다. namespace 분리와 디스크 데이터의 별도 복사는 같은 개념이 아닙니다.
 */
static int do_new_mount(struct path *path, const char *fstype, int sb_flags,
			int mnt_flags, const char *name, void *data)
{
	struct file_system_type *type;
	struct fs_context *fc;
	const char *subtype = NULL;
	int err = 0;

	if (!fstype)
		return -EINVAL;

	type = get_fs_type(fstype);
	if (!type)
		return -ENODEV;

	if (type->fs_flags & FS_HAS_SUBTYPE) {
		subtype = strchr(fstype, '.');
		if (subtype) {
			subtype++;
			if (!*subtype) {
				put_filesystem(type);
				return -EINVAL;
			}
		}
	}

