/* 학습 해설
 * 파일 잠금 · 협력적 동기화
 * 서로 다른 프로세스가 같은 파일의 일부를 동시에 수정하는 일을 조절해야 합니다.
 * POSIX 레코드 잠금은 범위와 소유 관계를 기록하고 충돌을 검사합니다. 일반적인 advisory 잠금은 참여하는 프로그램이 규칙을 지켜야 합니다. flock·POSIX·OFD 잠금은 소유·해제 의미가 다릅니다.
 * fcntl 잠금의 범위와 프로세스 수명·fd close 의미를 확인합니다. 파일을 잠근다고 모든 프로그램의 일반 write가 자동 금지된다고 가정하지 않습니다.
 */
int posix_lock_file(struct file *filp, struct file_lock *fl,
			struct file_lock *conflock)
{
	return posix_lock_inode(file_inode(filp), fl, conflock);
}
EXPORT_SYMBOL(posix_lock_file);

/**
 * posix_lock_inode_wait - Apply a POSIX-style lock to a file
 * @inode: inode of file to which lock request should be applied
 * @fl: The lock to be applied
 *
 * Apply a POSIX style lock request to an inode.
 */
static int posix_lock_inode_wait(struct inode *inode, struct file_lock *fl)
{
	int error;
	might_sleep ();
	for (;;) {
		error = posix_lock_inode(inode, fl, NULL);
		if (error != FILE_LOCK_DEFERRED)
			break;
		error = wait_event_interruptible(fl->c.flc_wait,
						 list_empty(&fl->c.flc_blocked_member));
		if (error)
			break;

