/* 학습 해설
 * Poll·Epoll · 준비된 I/O만 처리
 * 많은 소켓을 다룰 때 매번 모든 fd를 반복 검사하는 비용을 줄일 수 있습니다.
 * epoll은 관심 목록과 준비된 항목을 관리합니다. LT는 준비 상태를 계속 알리고 ET는 상태 변화 통지를 중심으로 동작합니다. 준비 통지는 작업 완료 통지와 다르며 실제 read는 다시 실패하거나 일부만 읽을 수 있습니다.
 * ET에서는 비블로킹 fd로 EAGAIN까지 처리하는 패턴을 학습합니다. epoll_wait 결과만으로 요청 전체의 처리 완료를 가정하지 않습니다.
 */
static int ep_poll(struct eventpoll *ep, struct epoll_event __user *events,
		   int maxevents, struct timespec64 *timeout)
{
	int res, eavail, timed_out = 0;
	u64 slack = 0;
	wait_queue_entry_t wait;
	ktime_t expires, *to = NULL;

	lockdep_assert_irqs_enabled();

	if (timeout && (timeout->tv_sec | timeout->tv_nsec)) {
		slack = select_estimate_accuracy(timeout);
		to = &expires;
		*to = timespec64_to_ktime(*timeout);
	} else if (timeout) {
		/*
		 * Avoid the unnecessary trip to the wait queue loop, if the
		 * caller specified a non blocking operation.
		 */
		timed_out = 1;
	}

	/*
	 * This call is racy: We may or may not see events that are being added
	 * to the ready list under the lock (e.g., in IRQ callbacks). For cases
	 * with a non-zero timeout, this thread will check the ready list under
	 * lock and will add to the wait queue.  For cases with a zero
	 * timeout, the user by definition should not care and will have to
	 * recheck again.
	 */

