/* 학습 해설
 * Splice · 커널 안의 데이터 전달
 * 파일과 소켓 사이의 데이터를 매번 사용자 버퍼로 왕복 복사하는 비용을 줄이고 싶을 수 있습니다.
 * pipe buffer와 페이지 참조 등을 이용해 커널 내부 데이터 경로를 연결합니다. 지원되는 fd·파일시스템·장치에 따라 복사나 fallback이 남을 수 있어 모든 상황의 절대 무복사 보장은 아닙니다.
 * splice는 pipe와 fd의 조건을 확인하고 부분 처리량·EAGAIN을 처리합니다. sendfile과 일반 read/write의 적용 경로를 구분합니다.
 */
ssize_t splice_to_pipe(struct pipe_inode_info *pipe,
		       struct splice_pipe_desc *spd)
{
	unsigned int spd_pages = spd->nr_pages;
	unsigned int tail = pipe->tail;
	unsigned int head = pipe->head;
	unsigned int mask = pipe->ring_size - 1;
	ssize_t ret = 0;
	int page_nr = 0;

	if (!spd_pages)
		return 0;

	if (unlikely(!pipe->readers)) {
		send_sig(SIGPIPE, current, 0);
		ret = -EPIPE;
		goto out;
	}

	while (!pipe_full(head, tail, pipe->max_usage)) {
		struct pipe_buffer *buf = &pipe->bufs[head & mask];

		buf->page = spd->pages[page_nr];
		buf->offset = spd->partial[page_nr].offset;
		buf->len = spd->partial[page_nr].len;
		buf->private = spd->partial[page_nr].private;

