/* 학습 해설
 * TCP 혼잡 제어 · CUBIC·BBR와 전송률
 * 네트워크 용량을 넘는 송신으로 손실과 지연이 커지는 일을 줄여야 합니다.
 * 혼잡 제어 모듈은 ACK·손실·RTT·전송률 등의 관측으로 송신 제약을 조절합니다. CUBIC과 BBR은 서로 다른 모델을 사용하며 사용 가능 목록과 기본 선택은 빌드·설정에 따라 달라집니다.
 * tcp_available_congestion_control과 tcp_congestion_control을 조회합니다. 커널 버전만으로 특정 모듈이 항상 활성이라고 가정하지 않습니다.
 */
int tcp_set_congestion_control(struct sock *sk, const char *name, bool load,
			       bool cap_net_admin)
{
	struct inet_connection_sock *icsk = inet_csk(sk);
	const struct tcp_congestion_ops *ca;
	int err = 0;

	if (icsk->icsk_ca_dst_locked)
		return -EPERM;

	rcu_read_lock();
	if (!load)
		ca = tcp_ca_find(name);
	else
		ca = tcp_ca_find_autoload(name);

	/* No change asking for existing value */
	if (ca == icsk->icsk_ca_ops) {
		icsk->icsk_ca_setsockopt = 1;
		goto out;
	}

	if (!ca)
		err = -ENOENT;
	else if (!((ca->flags & TCP_CONG_NON_RESTRICTED) || cap_net_admin))
		err = -EPERM;

