/* 학습 해설
 * FQ-CoDel · 흐름 분리와 큐 지연
 * 너무 큰 큐는 처리량이 좋아 보여도 응답 지연을 늘리는 bufferbloat를 만들 수 있습니다.
 * FQ는 흐름을 분리해 공정하게 서비스하고 CoDel은 큐 체류 시간으로 혼잡을 제어합니다. 패킷 드롭·ECN 표시가 혼잡 피드백으로 사용될 수 있습니다.
 * tc -s qdisc show로 큐 discipline을 조회합니다. 큰 버퍼를 추가하는 것과 지연을 줄이는 것은 같은 해결책이 아닙니다.
 */
static struct sk_buff *fq_codel_dequeue(struct Qdisc *sch)
{
	struct fq_codel_sched_data *q = qdisc_priv(sch);
	struct sk_buff *skb;
	struct fq_codel_flow *flow;
	struct list_head *head;

begin:
	head = &q->new_flows;
	if (list_empty(head)) {
		head = &q->old_flows;
		if (list_empty(head))
			return NULL;
	}
	flow = list_first_entry(head, struct fq_codel_flow, flowchain);

	if (flow->deficit <= 0) {
		flow->deficit += q->quantum;
		list_move_tail(&flow->flowchain, &q->old_flows);
		goto begin;
	}

	skb = codel_dequeue(sch, &sch->qstats.backlog, &q->cparams,
			    &flow->cvars, &q->cstats, qdisc_pkt_len,
			    codel_get_enqueue_time, drop_func, dequeue_func);

