/* 학습 해설
 * XDP·eBPF 패킷 처리 · 이른 경로
 * 일반 네트워크 스택 처리 전에 빠르게 패킷을 분류하거나 버릴 수 있으면 비용을 줄일 수 있습니다.
 * XDP 프로그램은 허용된 문맥에서 패킷을 검사해 PASS·DROP·TX·REDIRECT 같은 동작을 선택합니다. 실행 위치와 드라이버 지원은 native·generic 등의 모드에 따라 다릅니다. verifier 제약과 패킷 경계 검사가 필요합니다.
 * 작동 모드와 프로그램 권한을 확인하고 데이터를 읽기 전에 data_end 경계를 검사합니다. 모든 드라이버가 모든 XDP 기능을 지원한다고 가정하지 않습니다.
 */
static __always_inline u32 bpf_prog_run_xdp(const struct bpf_prog *prog,
					    struct xdp_buff *xdp)
