/* 학습 해설
 * Cgroup v2 · 자원 제한과 계층
 * 여러 프로세스를 그룹으로 묶어 CPU·메모리·I/O 사용을 관리해야 합니다.
 * 계층의 그룹에 태스크를 소속시키고 controller가 자원을 계산·제한합니다. v2는 통합 계층과 controller 활성화 규칙을 사용합니다. 자원 제한과 namespace의 보기를 분리하는 기능은 다릅니다.
 * /proc/self/cgroup과 /sys/fs/cgroup을 조회합니다. 그룹 제한 때문에 호스트 여유와 별개로 throttling이나 그룹 OOM이 발생할 수 있습니다.
 */
int cgroup_mkdir(struct kernfs_node *parent_kn, const char *name, umode_t mode)
{
	struct cgroup *parent, *cgrp;
	int ret;

	/* do not accept '\n' to prevent making /proc/<pid>/cgroup unparsable */
	if (strchr(name, '\n'))
		return -EINVAL;

	parent = cgroup_kn_lock_live(parent_kn, false);
	if (!parent)
		return -ENODEV;

	if (!cgroup_check_hierarchy_limits(parent)) {
		ret = -EAGAIN;
		goto out_unlock;
	}

	cgrp = cgroup_create(parent, name, mode);
	if (IS_ERR(cgrp)) {
		ret = PTR_ERR(cgrp);
		goto out_unlock;
	}

