/* 학습 해설
 * Seccomp · 시스템 콜 제한
 * 프로그램이 필요한 시스템 콜만 사용하도록 공격 표면을 줄일 수 있습니다.
 * 필터는 syscall 번호·아키텍처·인자 등의 정보를 기준으로 허용·오류·종료·통지 등 결정을 내립니다. syscall의 포인터가 가리키는 임의 메모리 내용을 필터에서 직접 읽는 인터페이스는 아닙니다.
 * 동작에 필요한 syscall을 분석해 정책을 만듭니다. seccomp는 파일 권한·namespace·LSM을 전부 대신하지 않으며 아키텍처별 syscall 번호 검증이 필요합니다.
 */
int __secure_computing(const struct seccomp_data *sd)
{
	int mode = current->seccomp.mode;
	int this_syscall;

	if (IS_ENABLED(CONFIG_CHECKPOINT_RESTORE) &&
	    unlikely(current->ptrace & PT_SUSPEND_SECCOMP))
		return 0;

	this_syscall = sd ? sd->nr :
		syscall_get_nr(current, current_pt_regs());

	switch (mode) {
	case SECCOMP_MODE_STRICT:
		__secure_computing_strict(this_syscall);  /* may call do_exit */
		return 0;
	case SECCOMP_MODE_FILTER:
		return __seccomp_filter(this_syscall, sd, false);
	/* Surviving SECCOMP_RET_KILL_* must be proactively impossible. */
	case SECCOMP_MODE_DEAD:
		WARN_ON_ONCE(1);
		do_exit(SIGKILL);
		return -1;
	default:
		BUG();
	}

/* 학습 해설
 * LSM·SELinux·AppArmor · 정책 검사 지점
 * 기본 Unix 권한 외에도 정책에 따라 작업을 허용하거나 거부해야 합니다.
 * LSM hook이 파일·프로세스·네트워크 작업의 보안 검사 지점을 제공합니다. SELinux는 label과 정책, AppArmor는 프로파일 기반 정책을 사용합니다. 정책 표현과 작동 구성은 서로 다릅니다.
 * 거부 로그와 실제 활성 LSM·정책을 함께 확인합니다. 일반 파일 권한이 맞는데도 LSM 정책에 의해 거부될 수 있습니다.
 */
int security_file_open(struct file *file)
{
	int ret;

	ret = call_int_hook(file_open, file);
	if (ret)
		return ret;

	return fsnotify_open_perm(file);
}

/**
 * security_file_post_open() - Evaluate a file after it has been opened
 * @file: the file
 * @mask: access mask
 *
 * Evaluate an opened file and the access mask requested with open(). The hook
 * is useful for LSMs that require the file content to be available in order to
 * make decisions.
 *
 * Return: Returns 0 if permission is granted.
 */
int security_file_post_open(struct file *file, int mask)
{
	return call_int_hook(file_post_open, file, mask);
}

/* 학습 해설
 * eBPF Verifier·Map · 제한된 프로그램 실행
 * 관찰·네트워크·정책을 확장하면서 임의 잘못된 커널 메모리 접근을 막아야 합니다.
 * verifier는 레지스터·스택·포인터 범위·제어 흐름 등을 추적해 프로그램 타입의 제약을 검사합니다. map은 프로그램과 사용자 공간의 상태 공유 수단입니다. 검증 통과가 애플리케이션 로직의 정답을 증명하지는 않습니다.
 * 프로그램 타입·helper·map 수명·권한을 확인합니다. 검증 로그로 거부 지점을 읽고 타입에 따라 허용되는 접근이 다른지 비교합니다.
